#   C:\Windows\SysWOW64\WindowsPowerShell\v1.0\powershell.exe -ep bypass -f \\tsclient\Downloads\probe-expenses.ps1 > \\tsclient\Downloads\probe-expenses.out.txt 2>&1
#
# ASCII-only source; Cyrillic is built from char codes (see gen-probe-expenses.py).

